with open('/workdir/disk.img', 'r', encoding='latin-1') as f:
    content = f.read()

# Find lines with non-whitespace, non-newline characters
lines = []
current_line = ''
in_line = False

for char in content:
    if char in '\n\r\t ':
        if not in_line:
            lines.append((current_line, ''))
            current_line = ''
            in_line = False
        else:
            current_line += char
    else:
        if not in_line:
            current_line += char
            in_line = True

# Print last line
if current_line:
    lines.append((current_line, ''))

# Now filter out empty lines and find meaningful content
for line, _ in lines:
    if line.strip() and not line.strip().startswith('\x00') and not line.strip().startswith('\x01'):
        # Check if line contains potential flag
        if any(c.isprintable() or c in '\n\r\t' for c in line):
            print(repr(line))
""}
